ndler.SpawnInitial(_handler.SpawnPopulations[i], spawndists[i]); newCount += _handler.GetCurrentCount(_handler.SpawnPopulations[i]); yield return new WaitForEndOfFrame(); } } SendReply(arg, $"Filled SpawnPopulations | Old: {oldCount} | New: {newCount}"); } _handler.StartCoroutine("SpawnTick"); runningSpawnFill = false; yield return null; }  [ConsoleCommand("sc.raisedensity")] void ccmdSpawnRaiseDensity(ConsoleSystem.Arg arg) { var _handler = SpawnHandler.Instance; if(arg.Connection != null && arg.Connection.authLevel < 2) return; float percentage = 0f; string populationname = string.Empty; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "You need to provide a number as percantage and a valid SpawnPopulation name"); return; } float percent = -1; if (float.TryParse(arg.Args[0], out percent)) percentage = percent; else { SendReply(arg, "You need to provide a number as percentage"); return; } if (percentage > 100f) { percentage = 100f; SendReply(arg, "Percentage was limited to 100% to avoid server freezes"); } populationname = arg.Args[1]; bool raiseAll = false; if (populationname == "all") raiseAll = true; SendReply(arg, $"Calling raise of density with '{percentage}' percent for '{populationname}'"); ServerMgr.Instance.StartCoroutine(SpawnRaiseDensity(percentage, populationname, raiseAll, arg)); }  IEnumerator SpawnRaiseDensity(float percentage, string populationname, bool raiseAll, ConsoleSystem.Arg arg) { runningSpawnRaiseDensity = true; var _handler = SpawnHandler.Instance; _handler.StopCoroutine("SpawnTick"); bool findany = false; if (!raiseAll) { bool fullMatch = false; for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { if ((_handler.SpawnPopulations[i].name.StartsWith(populationname) || _handler.SpawnPopulations[i].name.EndsWith(populationname)) && !fullMatch) { if (_handler.SpawnPopulations[i].name == populationname) fullMatch = true; float oldDensity = _handler.SpawnPopulations[i].TargetDensity; float increaseDensity = 0f; if (oldDensity > 0f) increaseDensity = _handler.SpawnPopulations[i].TargetDensity / 100 * percentage; else { object backupDensity = null; if (spawnDefaults.TryGetValue(_handler.SpawnPopulations[i].name, out backupDensity)) increaseDensity = Convert.ToSingle(backupDensity) / 100 * percentage; else increaseDensity = _handler.SpawnPopulations[i].TargetDensity / 100 * percentage; } float newDensity = (float)Math.Round((double)(oldDensity+increaseDensity)); _targetDensity.SetValue(_handler.SpawnPopulations[i], newDensity); (SpawnPopulation[_handler.SpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = _handler.SpawnPopulations[i].TargetDensity; SendReply(arg, $"Raised density of '{_handler.SpawnPopulations[i].name}' | Old: {oldDensity} | New: {newDensity}"); findany = true; } } } if (!findany) SendReply(arg, $"SpawnPopulation '{populationname}' not found"); else { SendReply(arg, "New raised density's set and saved."); Config["Spawn", "Population"] = SpawnPopulation; Config.Save(); string type = arg.Args[1]; arg.Args = new string[] { type }; NextTick(() => ccmdSpawnFill(arg)); } } else { SendReply(arg, $"Raising all SpawnPopulation density's by '{percentage}' percent"); for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { float oldDensity = _handler.SpawnPopulations[i].TargetDensity; float increaseDensity = _handler.SpawnPopulations[i].TargetDensity / 100 * percentage; float newDensity = (float)Math.Round((double)(oldDensity+increaseDensity)); _targetDensity.SetValue(_handler.SpawnPopulations[i], newDensity); (SpawnPopulation[_handler.SpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = _handler.SpawnPopulations[i].TargetDensity; } } SendReply(arg, "New raised density's set and saved."); Config["Spawn", "Population"] = SpawnPopulation; Config.Save(); arg.Args = null; NextTick(() => ccmdSpawnFill(arg)); } _handler.StartCoroutine("SpawnTick"); runningSpawnRaiseDensity = false; yield return null; }  [ConsoleCommand("sc.lowerdensity")] void ccmdSpawnLowerDensity(ConsoleSystem.Arg arg) { var _handler = SpawnHandler.Instance; if(arg.Connection != null && arg.Connection.authLevel < 2) return; float percentage = 0f; string populationname = string.Empty; if (arg.Args == null || arg.Args.Length < 2) { SendReply(arg, "You need to provide a percentage number and a valid SpawnPopulation name"); return; } float percent = -1; if (float.TryParse(arg.Args[0], out percent)) percentage = percent; else { SendReply(arg, "You need to provide a number as percentage"); return; } populationname = arg.Args[1]; bool lowerAll = false; if (populationname == "all") lowerAll = true; if (percentage > 100f) { percentage = 100f; SendReply(arg, "Percentage was limited to 100%"); } bool force = false; if (arg.Args.Length >= 3 && arg.Args[2] == "force") force = true; if (lowerAll && percentage == 100f && !force) { SendReply(arg, "Canceled: Lowering all by 100% would set all to zero pop"); SendReply(arg, "You need to add 'force' as additional argument!"); return; } SendReply(arg, $"Calling lower with '{percentage}' percent for '{populationname}'"); ServerMgr.Instance.StartCoroutine(SpawnLowerDensity(percentage, populationname, lowerAll, arg)); }  IEnumerator SpawnLowerDensity(float percentage, string populationname, bool lowerAll, ConsoleSystem.Arg arg) { runningSpawnLowerDensity = true; var _handler = SpawnHandler.Instance; _handler.StopCoroutine("SpawnTick"); bool findany = false; if (!lowerAll) { bool fullMatch = false; for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { if ((_handler.SpawnPopulations[i].name.StartsWith(populationname) || _handler.SpawnPopulations[i].name.EndsWith(populationname)) && !fullMatch) { if (_handler.SpawnPopulations[i].name == populationname) fullMatch = true; float oldDensity = _handler.SpawnPopulations[i].TargetDensity; float decreaseDensity = _handler.SpawnPopulations[i].TargetDensity / 100 * percentage; float newDensity = -1f; if (percentage == 100f) newDensity = 0f; else newDensity = (float)Math.Round((double)(oldDensity-decreaseDensity)); _targetDensity.SetValue(_handler.SpawnPopulations[i], newDensity); (SpawnPopulation[_handler.SpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = _handler.SpawnPopulations[i].TargetDensity; SendReply(arg, $"Lowered density of '{_handler.SpawnPopulations[i].name}' | Old: {oldDensity} | New: {newDensity}"); findany = true; } } } if (!findany) SendReply(arg, $"SpawnPopulation '{populationname}' not found"); else { SendReply(arg, $"New lowered density's set and saved."); Config["Spawn", "Population"] = SpawnPopulation; Config.Save(); NextTick(() => ccmdEnforceLimits(arg)); } } else { SendReply(arg, $"Lowering all SpawnPopulation density's by '{percentage}' percent"); for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { float oldDensity = _handler.SpawnPopulations[i].TargetDensity; float decreaseDensity = _handler.SpawnPopulations[i].TargetDensity / 100 * percentage; float newDensity = -1f; if (percentage == 100f) newDensity = 0f; else newDensity = (float)Math.Round((double)(oldDensity-decreaseDensity)); _targetDensity.SetValue(_handler.SpawnPopulations[i], newDensity); (SpawnPopulation[_handler.SpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = _handler.SpawnPopulations[i].TargetDensity; } } SendReply(arg, $"New lowered density's set and saved"); Config["Spawn", "Population"] = SpawnPopulation; Config.Save(); NextTick(() => ccmdEnforceLimits(arg)); } _handler.StartCoroutine("SpawnTick"); runningSpawnLowerDensity = false; yield return null; }  [ConsoleCommand("sc.kill")] void ccmdSpawnKill(ConsoleSystem.Arg arg) { var _handler = SpawnHandler.Instance; if(arg.Connection != null && arg.Connection.authLevel < 2) return; string populationname = string.Empty; if (arg.Args == null || arg.Args.Length < 1) { SendReply(arg, $"You need to provide a valid SpawnPopulation name"); return; } populationname = arg.Args[0]; bool killAll = false; if (populationname == "all") killAll = true; SendReply(arg, $"Calling kill for '{populationname}'"); ServerMgr.Instance.StartCoroutine(SpawnKill(populationname, killAll, arg)); }  IEnumerator SpawnKill(string populationname, bool killAll, ConsoleSystem.Arg arg) { runningSpawnKill = true; var _handler = SpawnHandler.Instance; _handler.StopCoroutine("SpawnTick"); bool findany = false; SpawnPopulation[] spawnpops = _handler.SpawnPopulations.ToArray(); int countDeleted = 0; bool fullMatch = false; bool junkPiles = false; for (int i = 0; i < spawnpops.Length; i++) { if (!(spawnpops[i] == null)) { if ((spawnpops[i].name.StartsWith(populationname) || (spawnpops[i].name.EndsWith(populationname)) && !fullMatch) || killAll) { if (spawnpops[i].name == populationname) fullMatch = true; Spawnable[] array = _handler.FindAll(spawnpops[i]); int count = array.Length; foreach (Spawnable current in array) { BaseEntity baseEntity = current.gameObject.ToBaseEntity(); if (baseEntity.IsValid()) { if (baseEntity is JunkPile) { (baseEntity as JunkPile).SinkAndDestroy(); junkPiles = true; } else baseEntity.Kill(BaseNetworkable.DestroyMode.None); countDeleted++; } else { GameManager.Destroy(current.gameObject, 0f); countDeleted++; } } if (!killAll) { if (junkPiles) SendReply(arg, $"Forced deletion of '{spawnpops[i].name}' | Old: {count} | New: {_handler.GetCurrentCount(spawnpops[i])}(DELAYED)"); else SendReply(arg, $"Forced deletion of '{spawnpops[i].name}' | Old: {count} | New: {_handler.GetCurrentCount(spawnpops[i])}"); } findany = true; yield return new WaitForEndOfFrame(); } } } if (!findany && !killAll) SendReply(arg, $"SpawnPopulation '{populationname}' not found"); if (findany && killAll) { _handler.UpdateDistributions(); SendReply(arg, $"SapwnHandler cleaned the map of '{countDeleted}' objects"); } _handler.StartCoroutine("SpawnTick"); runningSpawnKill = false; yield return null; }  [ConsoleCommand("sc.enforcelimits")] void ccmdEnforceLimits(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; bool forceAll = false; if (arg.Args != null && arg.Args.Length > 0) { if (arg.Args[0].ToLower() == "all") forceAll = true; } SendReply(arg, $"Enforcing population limits"); NextTick(()=> ServerMgr.Instance.StartCoroutine(EnforceLimits(forceAll, arg))); }  IEnumerator EnforceLimits(bool forceAll, ConsoleSystem.Arg arg) { runningEnforceLimits = true; var _handler = SpawnHandler.Instance; SpawnDistribution[] spawndists =  (SpawnDistribution[])_SpawnDistributions.GetValue(_handler); int countDeleted = 0; for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { SpawnPopulation spawnPopulation = _handler.SpawnPopulations[i]; SpawnDistribution distribution = spawndists[i]; if (forceAll || spawnPopulation.EnforcePopulationLimits) { int targetCount = _handler.GetTargetCount(spawnPopulation, distribution); Spawnable[] array = _handler.FindAll(spawnPopulation); if (array.Length <= targetCount) continue; int num = array.Length - targetCount; foreach (Spawnable current in array.Take(num)) { BaseEntity baseEntity = current.gameObject.ToBaseEntity(); if (baseEntity.IsValid()) { baseEntity.Kill(BaseNetworkable.DestroyMode.None); countDeleted++; } else { GameManager.Destroy(current.gameObject, 0f); countDeleted++; } } } } yield return new WaitForEndOfFrame(); } SendReply(arg, $"Enforced limits on '{countDeleted}' objects"); runningEnforceLimits = false; yield return null; }  [ConsoleCommand("sc.reload")] void ccmdSpawnReload(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { var _handler = SpawnHandler.Instance; LoadConfig(); LoadVariables(); FillPopulations.Clear(); FillJobs.Clear(); heartbeatOn = false; SpawnPopLoad(); SpawnGroupLoad(); GetPopulationNames(); if (reloadWithIncludedFill) NextTick(() => { _handler.FillPopulations(); if(enableSpawnGroups) _handler.FillGroups(); }); if (FillJobs.Count > 0) SendReply(arg, $"Planned {FillJobs.Count} job(s) for spawn population"); if (reloadWithIncludedFill) { if (enableSpawnGroups) SendReply(arg, $"Updated and initially filled SpawnPopulations and SpawnGroups"); else SendReply(arg, $"Updated and initially filled SpawnPopulations"); } else { if (enableSpawnGroups) SendReply(arg, $"Updated SpawnPopulation and SpawnGroup settings"); else SendReply(arg, $"Updated SpawnPopulation settings"); } }); }  [ConsoleCommand("sc.report")] void ccmdGetReport(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { var _handler = SpawnHandler.Instance; SpawnDistribution[] spawndists = (SpawnDistribution[])_SpawnDistributions.GetValue(_handler); TextTable textTable = new TextTable(); textTable.AddColumn("SpawnPopulation"); textTable.AddColumn("Current"); textTable.AddColumn("Limits"); int totalCurrent = 0; int totalLimits = 0; for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { SpawnPopulation spawnPopulation = _handler.SpawnPopulations[i]; SpawnDistribution spawnDistribution = spawndists[i]; if (spawnPopulation != null) { if (spawnDistribution != null) { var curr = _handler.GetCurrentCount(spawnPopulation); var lmt = _handler.GetTargetCount(spawnPopulation, spawnDistribution); textTable.AddRow(new string[] { spawnPopulation.name.ToString(), curr.ToString(), lmt.ToString() }); totalCurrent += curr; totalLimits += lmt; } } } } textTable.AddRow(new string[] { "TOTAL:", totalCurrent.ToString(), totalLimits.ToString() }); SendReply(arg, "\n>> Report:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.spawnpopulations")] void ccmdGetPopulations(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { var _handler = SpawnHandler.Instance; TextTable textTable = new TextTable(); textTable.AddColumn("Name"); textTable.AddColumn("Density"); textTable.AddColumn("Rate"); textTable.AddColumn("Limiting"); if (enablePopulationPrefabs) textTable.AddColumn("Prefabs"); textTable.AddColumn("ResourceFolder"); for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { SpawnPopulation spawnPopulation = _handler.SpawnPopulations[i]; if (enablePopulationPrefabs) { var prefabs = (Prefab<Spawnable>[])_PrefabsField.GetValue(spawnPopulation); textTable.AddRow(new string[] { spawnPopulation.name.ToString(), spawnPopulation.TargetDensity.ToString(), spawnPopulation.SpawnRate.ToString(), spawnPopulation.EnforcePopulationLimits.ToString(), prefabs.Length.ToString(), spawnPopulation.ResourceFolder }); } else textTable.AddRow(new string[] { spawnPopulation.name.ToString(), spawnPopulation.TargetDensity.ToString(), spawnPopulation.SpawnRate.ToString(), spawnPopulation.EnforcePopulationLimits.ToString(), spawnPopulation.ResourceFolder }); } } SendReply(arg, "\n>> SpawnPopulations:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.restoredensitys")] void ccmdRestoreDensitys(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { var _handler = SpawnHandler.Instance; if (spawnDefaults == null || spawnDefaults.Count == 0) { spawnDefaults = new Dictionary<string, object>(); defaultSpawnPops = getFile($"{this.Title}_defaults"); spawnDefaults = defaultSpawnPops["Backup"] as Dictionary<string, object>; } if (spawnDefaults == null || spawnDefaults.Count == 0) { SendReply(arg, "Default SpawnPopulations not found or file missing."); return; } for (int i = 0; i < _handler.SpawnPopulations.Length; i++) { if (!(_handler.SpawnPopulations[i] == null)) { float newDensity = Convert.ToSingle(spawnDefaults[_handler.SpawnPopulations[i].name]); _targetDensity.SetValue(_handler.SpawnPopulations[i], newDensity); (SpawnPopulation[_handler.SpawnPopulations[i].name] as Dictionary<string,object>)["spawndensity"] = newDensity; } } Config["Spawn", "Population"] = SpawnPopulation; Config.Save(); SendReply(arg, "Reverted SpawnPopulation density's to their defaults"); NextTick(() => { ccmdEnforceLimits(arg); ccmdSpawnFill(arg); }); }); }  [ConsoleCommand("sc.groupspawners")] void ccmdGetSpanwers(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; if (!enableSpawnGroups) { SendReply(arg, $"Command inactive. SpawnGroups not activated"); return; } NextFrame(()=> { string filterTxt = string.Empty; if (arg.Args != null && arg.Args.Length > 0) filterTxt = arg.Args[0]; TextTable textTable = new TextTable(); textTable.AddColumn("Name"); if (enableGroupTickData) textTable.AddColumn("MaxObj"); textTable.AddColumn("Respawn (s)"); if (enableGroupTickData) textTable.AddColumn("perTick"); textTable.AddColumn("Monument"); List<string>monumentnames = new List<string>(); foreach (var monument in UnityEngine.Object.FindObjectsOfType<MonumentInfo>()) { if (monumentnames.Contains(monument.name)) continue; monumentnames.Add(monument.name); List<string>groupnames = new List<string>(); foreach(var group in monument.gameObject.GetComponentsInChildren<SpawnGroup>()) { if (!string.IsNullOrEmpty(filterTxt) && !PrefabCut(monument.name).Contains(filterTxt)) continue; if (groupnames.Contains(group.name)) continue; if (group.name.StartsWith("door_barricade") || group.name.StartsWith("Barricades") || group.name.StartsWith("Ore")) continue; groupnames.Add(group.name); if (enableGroupTickData) textTable.AddRow(new string[] { group.name.ToString(), group.maxPopulation.ToString(), $"{group.respawnDelayMin} - {group.respawnDelayMax}", $"{group.numToSpawnPerTickMin} - {group.numToSpawnPerTickMax}", PrefabCut(monument.name) }); else textTable.AddRow(new string[] { group.name.ToString(), $"{group.respawnDelayMin} - {group.respawnDelayMax}", PrefabCut(monument.name) }); } } SendReply(arg, "\n>> GroupSpawners:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.dumpresources")] void ccmdDumpResources(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { TextTable textTable = new TextTable(); textTable.AddColumn("Name"); textTable.AddColumn("Count"); textTable.AddColumn("Type"); foreach (var t in GetCollectibles()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.ToString(), "Collectible" }); foreach (var t in GetOreNodes()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.Count().ToString(), "Ore" }); foreach (var t in GetAnimals()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.Count().ToString(), "Animals" }); SendReply(arg, "\n>> Resources:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.dumploot")] void ccmdDumpLoot(ConsoleSystem.Arg arg) { if(arg.Connection != null && arg.Connection.authLevel < 2) return; NextFrame(()=> { TextTable textTable = new TextTable(); textTable.AddColumn("Name"); textTable.AddColumn("Count"); textTable.AddColumn("Type"); foreach (var t in GetLootContainers()) textTable.AddRow(new string[] { t.Key.ToString(), t.Value.Count().ToString(), "Loot" }); SendReply(arg, "\n>> Loot:\n"+textTable.ToString()); }); }  [ConsoleCommand("sc.cmds")] void ccmdComandsList(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 2) return; var sb = new StringBuilder(); sb.AppendLine("\n==== Command List ================\n"); sb.AppendLine($"sc.cleardata".PadRight(21) + "| Clear Population and/or Group data by 'all', 'population' or 'groups"); sb.AppendLine($"sc.tickinterval".PadRight(21) + "| Show or set the Population tick interval in 'seconds'"); sb.AppendLine($"sc.fill".PadRight(21) + "| Fill all Populations or choosen one's by 'filter'"); sb.AppendLine($"sc.kill".PadRight(21) + "| Kill 'all' Populations or choosen one's by 'filter'"); sb.AppendLine($"sc.raisedensity".PadRight(21) + "| Raise Populations in 'percent' for 'all' or choosen one's by 'filter'"); sb.AppendLine($"sc.lowerdensity".PadRight(21) + "| Lower Populations in 'percent' for 'all' or choosen one's by 'filter'"); sb.AppendLine($"sc.enforcelimits".PadRight(21) + "| Enforce object limits on all Populations"); sb.AppendLine($"sc.reload".PadRight(21) + "| Reload the plugin after config changes"); sb.AppendLine($"sc.report".PadRight(21) + "| Display current Population objects with their limits"); sb.AppendLine($"sc.spawnpopulations".PadRight(21) + "| Display current Population settings"); sb.AppendLine($"sc.restoredensitys".PadRight(21) + "| Restore Population densitys to their defaults"); sb.AppendLine($"sc.groupspawners".PadRight(21) + "| Display SpawnGroup timers"); sb.AppendLine($"sc.dumpresources".PadRight(21) + "| Dump current resource amount"); sb.AppendLine($"sc.dumploot".PadRight(21) + "| Dump current complete loot amount (Populations and Groups)"); sb.AppendLine($"sc.cmds".PadRight(21) + "| Show this command"); sb.AppendLine($"sc.showconfig".PadRight(21) + "| Show current config options"); SendReply(arg, sb.ToString()); }  [ConsoleCommand("sc.showconfig")] void cmdShowConfig(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < 2) return; var sb = new StringBuilder(); sb.AppendLine("\n==== Current config options ================\n"); sb.AppendLine($"enableSpawnGroups".PadRight(26) + "| Loading and usage of SpawnGroups (optional)> "+ enableSpawnGroups); sb.AppendLine($"enableGroupTickData".PadRight(26) + "| Usage of SpawnGroups spawn per tick data (optional) > "+ enableGroupTickData); sb.AppendLine($"enablePopulationPrefabs".PadRight(26) + "| Loading and usage of SpawnPopulation prefabs (optional) > "+ enablePopulationPrefabs); sb.AppendLine($"normalizeDefaultVariables".PadRight(26) + "| Reverts server 'spawn' variables to defaults (recommended) > "+ normalizeDefaultVariables); sb.AppendLine($"reloadWithIncludedFill".PadRight(26) + "| Would also fill population after running 'sc.reload' > "+ reloadWithIncludedFill); sb.AppendLine($"logJobsToConsole".PadRight(26) + "| Would show 'spawnfillheartbeat' jobs in console > "+ logJobsToConsole); sb.AppendLine($"fixBarricadeStacking".PadRight(26) + "| Prevents stacking of doorbarricades > "+ fixBarricadeStacking); sb.AppendLine($"tickInterval".PadRight(26) + "| Interval between each population attempt (default 60) > "+ tickInterval); sb.AppendLine($"minSpawnsPerTick".PadRight(26) + "| Minimum objects to spawn per tick (default 100) > "+ minSpawnsPerTick); sb.AppendLine($"maxSpawnsPerTick".PadRight(26) + "| Maximum objects to spawn per tick (default 100) > "+ maxSpawnsPerTick); SendReply(arg, sb.ToString()); }  Dictionary<string, int> GetCollectibles() { return Resources.FindObjectsOfTypeAll<CollectibleEntity>().Where(c => c.isActiveAndEnabled && !c.ShortPrefabName.Contains("mushroom")).GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key.Remove(c.Key.Length - 12), c => c.Count()); }  Dictionary<string, IGrouping<string, BaseEntity>> GetOreNodes() { return Resources.FindObjectsOfTypeAll<BaseResource>().Where(c => c.isActiveAndEnabled).Cast<BaseEntity>().GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key.Remove(c.Key.Length - 4), c => c); }  Dictionary<string, IGrouping<string, BaseEntity>> GetLootContainers() { return Resources.FindObjectsOfTypeAll<LootContainer>().Where(c => c.isActiveAndEnabled).Cast<BaseEntity>().GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key, c => c); }  Dictionary<string, IGrouping<string, BaseEntity>> GetAnimals() { return Resources.FindObjectsOfTypeAll<BaseNpc>().Where(c => c.isActiveAndEnabled).Cast<BaseEntity>().GroupBy(c => c.ShortPrefabName).ToDictionary(c => c.Key, c => c); }  string PrefabCut(string name) => Oxide.Core.ExtensionMethods.Basename(name, ".prefab");  } }